        let expiration: Date
    }

    private var storage: [Key: CacheEntry] = [:]

    public init() {}

    public func set(_ value: Value, for key: Key, ttl: TimeInterval) {
        let expiration = Date().addingTimeInterval(ttl)
        storage[key] = CacheEntry(value: value, expiration: expiration)
