class WorkerPool
  def initialize(size:)
    @queue = SizedQueue.new(size * 2)
    @workers = size.times.map do
      Thread.new do
        catch(:done) do
          loop do
            task = @queue.pop
            throw :done if task == :terminate
            task.call
          end
        end
      end
    end
  end

  def post(&block)
    @queue << block
  end

  def shutdown
    @workers.size.times { @queue << :terminate }
    @workers.each(&:join)
  end
end

