import (
	"fmt"
	"hash/fnv"
	"sort"
	"strconv"
	"sync"
)

type HashRing struct {
	mu           sync.RWMutex
	replicas     int
	ring         []uint32
	ringMap      map[uint32]string
}

func NewHashRing(replicas int) *HashRing {
	return &HashRing{
		replicas: replicas,
		ringMap:  make(map[uint32]string),
	}
}

func (h *HashRing) hashKey(key string) uint32 {
	hasher := fnv.New32a()
	hasher.Write([]byte(key))
	return hasher.Sum32()
}

func (h *HashRing) AddNode(node string) {
	h.mu.Lock()
	defer h.mu.Unlock()

	for i := 0; i < h.replicas; i++ {
		vnodeKey := node + "#" + strconv.Itoa(i)
		hash := h.hashKey(vnodeKey)
		h.ring = append(h.ring, hash)
		h.ringMap[hash] = node
	}
	sort.Slice(h.ring, func(i, j int) bool { return h.ring[i] < h.ring[j] })
}

func (h *HashRing) GetNode(key string) (string, error) {
	h.mu.RLock()
	defer h.mu.RUnlock()

	if len(h.ring) == 0 {
		return "", fmt.Errorf("hash ring is empty")
	}

	hash := h.hashKey(key)
	idx := sort.Search(len(h.ring), func(i int) bool { return h.ring[i] >= hash })
	if idx == len(h.ring) {
		idx = 0 // Wrap around the ring
	}
	return h.ringMap[h.ring[idx]], nil
}

export type MachineState = 'IDLE' | 'FETCHING' | 'SUCCESS' | 'ERROR';
export type MachineEvent = 
  | { type: 'START' }
  | { type: 'RESOLVE'; data: string[] }
  | { type: 'REJECT'; error: Error }
  | { type: 'RESET' };

export interface MachineContext {
  state: MachineState;
  data?: string[];
  error?: Error;
}

export function transition(ctx: MachineContext, event: MachineEvent): MachineContext {
  switch (ctx.state) {
    case 'IDLE':
      if (event.type === 'START') {
        return { state: 'FETCHING' };
      }
      return ctx;
    case 'FETCHING':
      if (event.type === 'RESOLVE') {
        return { state: 'SUCCESS', data: event.data };
      }
      if (event.type === 'REJECT') {
        return { state: 'ERROR', error: event.error };
      }
      return ctx;
    case 'SUCCESS':
    case 'ERROR':
      if (event.type === 'RESET') {
        return { state: 'IDLE' };
      }
      return ctx;
  }
}

